/// A type that can be checked for membership of some item.
///
/// This trait abstracts over the different `contains`-style methods found on
/// standard library types (`str::contains`, `slice::contains`,
/// `HashSet::contains`, `HashMap::contains_key`, `Range::contains`, and so on)
/// so that generic code can perform membership checks uniformly.
///
/// For map types, membership is checked by key.
pub trait Container {
    /// The type of item that membership is checked against.
    type Item: ?Sized;

    /// Returns `true` if the container contains the given item.
    fn contains(&self, item: &Self::Item) -> bool;
}

impl Container for str {
    type Item = str;

    fn contains(&self, item: &str) -> bool {
        str::contains(self, item)
    }
}

impl Container for String {
    type Item = str;

    fn contains(&self, item: &str) -> bool {
        str::contains(self, item)
    }
}

impl<T: PartialEq, const N: usize> Container for [T; N] {
    type Item = T;

    fn contains(&self, item: &T) -> bool {
        <[T]>::contains(self, item)
    }
}

impl<T: PartialEq> Container for [T] {
    type Item = T;

    fn contains(&self, item: &T) -> bool {
        <[T]>::contains(self, item)
    }
}

impl<T: PartialEq> Container for Vec<T> {
